contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public {
        uint256 before = c.totalDistributed(); if (__ESBMC_reverted()) return;
        require(amount <= before);
        bool reverted;
        c.burn(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 after_ = c.totalDistributed(); if (__ESBMC_reverted()) return;
        assert(reverted || after_ == before - amount);
    }
}

