// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 amount) internal {
        uint256 before;
        try c.totalDistributed() returns (uint256 __r) { before = __r; } catch { return; }
        vm.assume(amount <= before);
        bool reverted;
        try c.burn(amount) { reverted = false; } catch { reverted = true; }
        uint256 after_;
        try c.totalDistributed() returns (uint256 __r) { after_ = __r; } catch { return; }
        assertTrue(reverted || after_ == before - amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
